package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RequestObjectSigningAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property request object signing alg of oauth client ")
  void test_request_object_signing_alg_v_o_builder() {
    Assertions.assertFalse(
        RequestObjectSigningAlgVO.nullValue().getRequestObjectSigningAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        RequestObjectSigningAlgVO.tryFrom(null).getRequestObjectSigningAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        RequestObjectSigningAlgVO.from("one").getRequestObjectSigningAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RequestObjectSigningAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RequestObjectSigningAlgVO.from("one").toString());
  }
}
